const PROCESSING_FEE = 5;

const SWORD_PREMIUM_WITH_INITIAL_ASSESSMENT = 110;

const premiumForItems = (items: Item[]): number =>
  items.length === 0 ? 0 : SWORD_PREMIUM_WITH_INITIAL_ASSESSMENT;

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quote = scenario.steps[0] as QuoteStep;
  const premium = premiumForItems(quote.items) + PROCESSING_FEE;
  return { results: [{ premium }] };
};
